CREATE TABLE wake_format(version TEXT PRIMARY KEY NOT NULL) STRICT;
CREATE TABLE connections(id TEXT PRIMARY KEY NOT NULL, provider TEXT NOT NULL, settings BLOB NOT NULL) STRICT;
CREATE TABLE credentials(connection_id TEXT NOT NULL REFERENCES connections(id), key TEXT NOT NULL, encrypted BLOB NOT NULL, PRIMARY KEY(connection_id,key)) STRICT;
CREATE TABLE work(connection_id TEXT NOT NULL REFERENCES connections(id), stream TEXT NOT NULL, operation TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 0, state_version TEXT NOT NULL DEFAULT '', state BLOB NOT NULL DEFAULT X'', next TEXT NOT NULL DEFAULT '', observed TEXT NOT NULL DEFAULT '', observed_completed INTEGER NOT NULL DEFAULT 0, observed_total INTEGER NOT NULL DEFAULT 0, acknowledged TEXT NOT NULL DEFAULT '', acknowledged_completed INTEGER NOT NULL DEFAULT 0, acknowledged_total INTEGER NOT NULL DEFAULT 0, failure TEXT NOT NULL DEFAULT '', PRIMARY KEY(connection_id,stream,operation)) STRICT;
CREATE TABLE artifacts(id TEXT PRIMARY KEY NOT NULL, connection_id TEXT NOT NULL REFERENCES connections(id), stream TEXT NOT NULL, operation TEXT NOT NULL, format TEXT NOT NULL, media_type TEXT NOT NULL, retrieved TEXT NOT NULL, hash TEXT NOT NULL, content BLOB NOT NULL, processed INTEGER NOT NULL DEFAULT 0, processing_next TEXT NOT NULL DEFAULT '', processing_failure TEXT NOT NULL DEFAULT '', requested_from TEXT NOT NULL DEFAULT '',requested_to TEXT NOT NULL DEFAULT '',reported_from TEXT NOT NULL DEFAULT '',reported_to TEXT NOT NULL DEFAULT '') STRICT;
CREATE TABLE candidates(artifact_id TEXT NOT NULL REFERENCES artifacts(id), authority TEXT NOT NULL, kind TEXT NOT NULL, scope TEXT NOT NULL, value TEXT NOT NULL, name TEXT NOT NULL, currency TEXT NOT NULL, PRIMARY KEY(artifact_id,authority,kind,scope,value)) STRICT;
CREATE TABLE attempts(id TEXT PRIMARY KEY NOT NULL, artifact_id TEXT NOT NULL REFERENCES artifacts(id), version TEXT NOT NULL, outcome TEXT NOT NULL, counts BLOB NOT NULL) STRICT;
CREATE INDEX attempts_artifact ON attempts(artifact_id,version,outcome);
CREATE TABLE records(artifact_id TEXT NOT NULL REFERENCES artifacts(id), version TEXT NOT NULL, location TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('trade','instrument','rejected')), data BLOB NOT NULL, PRIMARY KEY(artifact_id,version,location)) STRICT;
CREATE TABLE pacing(provider TEXT NOT NULL, policy TEXT NOT NULL, scope TEXT NOT NULL, next TEXT NOT NULL, PRIMARY KEY(provider,policy,scope)) STRICT;

CREATE TABLE scheduled(connection_id TEXT NOT NULL, stream TEXT NOT NULL, operation TEXT NOT NULL, enabled INTEGER NOT NULL, PRIMARY KEY(connection_id,stream,operation), FOREIGN KEY(connection_id,stream,operation) REFERENCES work(connection_id,stream,operation)) STRICT;
CREATE TABLE accounts(id TEXT PRIMARY KEY NOT NULL, singleton INTEGER NOT NULL UNIQUE CHECK(singleton=1), name TEXT NOT NULL, currency TEXT NOT NULL, connection_id TEXT NOT NULL REFERENCES connections(id), provider TEXT NOT NULL, stream TEXT NOT NULL, authority TEXT NOT NULL, kind TEXT NOT NULL, scope TEXT NOT NULL, value TEXT NOT NULL, artifact_id TEXT NOT NULL REFERENCES artifacts(id),rule TEXT NOT NULL DEFAULT 'account-authority/1') STRICT;
CREATE TABLE instruments(id TEXT PRIMARY KEY NOT NULL, source_key TEXT NOT NULL UNIQUE, name TEXT NOT NULL, ticker TEXT NOT NULL, kind TEXT NOT NULL, reported BLOB NOT NULL, reference_status TEXT NOT NULL, share_class_figi TEXT NOT NULL DEFAULT '', evidence_id TEXT NOT NULL DEFAULT '', reference_next TEXT NOT NULL DEFAULT '',rule TEXT NOT NULL DEFAULT 'qualified-instrument-reference/1') STRICT;
CREATE UNIQUE INDEX instrument_figi ON instruments(share_class_figi) WHERE share_class_figi<>'';
CREATE TABLE listings(id TEXT PRIMARY KEY NOT NULL, instrument_id TEXT NOT NULL REFERENCES instruments(id), venue TEXT NOT NULL, ticker TEXT NOT NULL, currency TEXT NOT NULL, figi TEXT NOT NULL DEFAULT '', UNIQUE(instrument_id,venue,ticker,currency)) STRICT;
CREATE TABLE executions(id TEXT PRIMARY KEY NOT NULL, account_id TEXT NOT NULL REFERENCES accounts(id), instrument_id TEXT NOT NULL REFERENCES instruments(id), listing_id TEXT NOT NULL REFERENCES listings(id), accepted BLOB NOT NULL, status TEXT NOT NULL, rule TEXT NOT NULL) STRICT;
CREATE TABLE event_links(account_id TEXT NOT NULL REFERENCES accounts(id), reference TEXT NOT NULL, execution_id TEXT NOT NULL REFERENCES executions(id), PRIMARY KEY(account_id,reference,execution_id)) STRICT;
CREATE TABLE execution_observations(artifact_id TEXT NOT NULL REFERENCES artifacts(id), version TEXT NOT NULL, location TEXT NOT NULL, execution_id TEXT REFERENCES executions(id), outcome TEXT NOT NULL, rule TEXT NOT NULL, PRIMARY KEY(artifact_id,version,location)) STRICT;
CREATE TABLE reference_settings(singleton INTEGER PRIMARY KEY CHECK(singleton=1), encrypted BLOB NOT NULL, failure TEXT NOT NULL DEFAULT '') STRICT;
CREATE TABLE reference_budget(singleton INTEGER PRIMARY KEY CHECK(singleton=1), window_start TEXT NOT NULL, used INTEGER NOT NULL, cooldown TEXT NOT NULL) STRICT;
CREATE TABLE reference_evidence(id TEXT PRIMARY KEY NOT NULL, retrieved TEXT NOT NULL, request BLOB NOT NULL, response BLOB NOT NULL, http_status INTEGER NOT NULL, headers BLOB NOT NULL) STRICT;
CREATE TABLE reference_cache(key TEXT PRIMARY KEY NOT NULL, status TEXT NOT NULL, records BLOB NOT NULL, expires TEXT NOT NULL, evidence_id TEXT NOT NULL REFERENCES reference_evidence(id)) STRICT;
CREATE TABLE instrument_reference_attempts(instrument_id TEXT NOT NULL REFERENCES instruments(id), evidence_id TEXT NOT NULL REFERENCES reference_evidence(id), status TEXT NOT NULL,rule TEXT NOT NULL, PRIMARY KEY(instrument_id,evidence_id)) STRICT;
